from lib import *
S = SS('k86')
F1 = [['list pods / get pods/log', 'yes'], ['delete pods', 'no(退出码 1)'], ['get configmaps/app-cfg', 'yes(resourceNames)'], ['get configmaps/other', 'no'], ['其他命名空间 / nodes / /metrics', 'no;/healthz yes']]
F2 = [['kubectl auth can-i', 'POST selfsubjectaccessreviews'], ['--as=alice', 'Impersonate-User: alice'], ['SubjectAccessReview', 'reason: RBAC: allowed by RoleBinding …'], ['加 system:masters 组', 'allowed=true,无 RBAC reason']]
F3 = [['can-i --list', 'SelfSubjectRulesReview'], ['22 行', '含 pods / configmaps / pods/log'], ['resourceRules 5 条', 'incomplete=false'], ['局限', '看不到 Webhook 授权器的规则']]
F4 = [['资源名写错', 'no + Warning'], ['--subresource=log', 'yes'], ['-q', '只看退出码'], ['--as-group', '组也参与鉴权']]
PANELS = [('f', 'flow', '鉴权查询'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("alice 在命名空间 k86 有 Role pod-reader(pods get/list、pods/log get、configmap app-cfg get/update)。can-i list pods → yes(退出码 0),delete pods → no(退出码 1),get pods/log → yes,get configmaps/app-cfg → yes,get configmaps/other → no(resourceNames 限制),update configmaps/app-cfg → yes。换到 default 命名空间、--all-namespaces、集群级资源 nodes 都是 no;非资源 URL /healthz → yes(system:public-info-viewer),/metrics → no。", f=fl(F1, cur=[0, 2], mark=[1, 3], done=[4]), t=tl(S(1), mark=lidx(S(1), 'delete pods', 'configmaps/other', '换成命名空间 default'), done=lidx(S(1), 'list pods', '/healthz')), kv=KV([['yes / no', '退出码 0 / 1,脚本里直接判断'], ['resourceNames', '精确到单个对象名'], ['范围', 'RoleBinding 只在自己的命名空间有效']], ['退出码'])),
    step("-v=8 看到 kubectl auth can-i 其实发出一次 POST https://…/apis/authorization.k8s.io/v1/selfsubjectaccessreviews,请求头带 Impersonate-User: alice,返回 201 Created。自己提交 SelfSubjectAccessReview 得到 allowed=true,reason 是 RBAC: allowed by RoleBinding \"alice-reader/k86\" of Role \"pod-reader\" to User \"alice\";直接提交 SubjectAccessReview(spec.user=alice)结果相同;delete pods allowed=false 且 reason 为空;给 SubjectAccessReview 加上 groups: [system:masters] 后 delete 变成 allowed=true,reason 为空(超级用户组由专门的授权器放行,没有 RBAC reason)。", f=fl(F2, cur=[0, 1], done=[2, 3]), t=tl(S(2), mark=lidx(S(2), 'Impersonate-User', 'selfsubjectaccessreviews'), done=lidx(S(2), '自己提交', '直接提交', 'system:masters')), kv=KV([['SelfSubjectAccessReview', '“我能不能”,用调用者自己的身份'], ['SubjectAccessReview', '“某人能不能”,可指定 user/groups,需要权限'], ['reason', '告诉你是哪条绑定放行的']], ['reason'])),
    step("kubectl auth can-i --list -n k86 --as=alice 共 22 行,其中和 pod-reader 相关的:pods [get list]、configmaps [app-cfg] [get update]、pods/log [get]。它背后是 SelfSubjectRulesReview:直接提交得到 incomplete=False、resourceRules 5 条、nonResourceRules 2 条、evaluationError=None。--list 来自 RBAC 等本地授权器的规则展开,Webhook 之类的授权器可能让结果不完整(此时 incomplete=true)。", f=fl(F3, cur=[0, 1, 2], mark=[3]), t=tl(S(3), mark=lidx(S(3), 'can-i --list'), done=lidx(S(3), '直接提交 SelfSubjectRulesReview')), kv=KV([['--list', '规则展开,方便人看'], ['incomplete', '为 true 时不能依赖列表'], ['精确判断', '用具体的 can-i 或 SAR']], ['--list'])),
    step("几个小陷阱:资源名写错(podz)只给 Warning: the server doesn't have a resource type 'podz',结果仍是 no;--subresource=log 的 get pods → yes;-q 不输出,只用退出码(这里 create pods 是 no,退出码 1);--as-group=system:masters 时 delete pods → yes——组也参与鉴权。", f=fl(F4, cur=[0, 3], done=[1, 2]), t=tl(S(4), mark=lidx(S(4), '资源名写错'), done=lidx(S(4), '--subresource=log', '-q', '--as=alice --as-group')), kv=KV([['no 不一定是没权限', '可能是名字写错、范围不对'], ['看 Warning', 'stderr 里有提示'], ['组也要写', '模拟时 --as-group 会改变结果']], ['no 不一定是没权限'])),
]
A = mkartk('k86', 86, 'Kubernetes,kubectl auth can-i,SelfSubjectAccessReview,SubjectAccessReview,RBAC,真实验证,动画演示',
    '在 kind 集群里拆开 kubectl auth can-i:它只是向 selfsubjectaccessreviews 发一次 POST(请求头带 Impersonate-User),返回 allowed 和 reason(RBAC: allowed by RoleBinding … of Role …);yes/no 对应退出码 0/1,resourceNames、命名空间范围、非资源 URL 都能查;--list 来自 SelfSubjectRulesReview(5 条 resourceRules,incomplete=false);资源名写错只给 Warning 且仍返回 no。',
    '怎么在不真正执行的前提下判断某个用户有没有某个权限?kubectl auth can-i 到底调了什么 API?reason 能告诉我什么?--list 可靠吗?这篇用 alice 的几条权限把 can-i 的各种用法都跑一遍,并直接提交三种 Review 对象。',
    [('0 / 1', 'can-i 的退出码:yes 为 0,no 为 1,可直接用在脚本里'), ('selfsubjectaccessreviews', 'can-i 背后调用的 API 资源;请求头带 --as 对应的 Impersonate-User'), ('incomplete=false', 'SelfSubjectRulesReview 结果完整的标志;Webhook 授权器会让它变成 true')],
    [('常见查询', '<p>alice 在命名空间 <code>k86</code> 有 Role <code>pod-reader</code>(pods get/list、pods/log get、configmap <code>app-cfg</code> get/update)。<code>can-i list pods</code> → yes(退出码 0),<code>delete pods</code> → no(退出码 1),<code>get pods/log</code> → yes,<code>get configmaps/app-cfg</code> → yes,<code>get configmaps/other</code> → no(<code>resourceNames</code> 限制),<code>update configmaps/app-cfg</code> → yes。换到 <code>default</code> 命名空间、<code>--all-namespaces</code>、集群级资源 <code>nodes</code> 都是 no;非资源 URL <code>/healthz</code> → yes(<code>system:public-info-viewer</code> 默认允许),<code>/metrics</code> → no。</p>'),
     ('背后的 API', '<p><code>-v=8</code> 能看到 <code>kubectl auth can-i</code> 只是发了一次 <code>POST https://…/apis/authorization.k8s.io/v1/selfsubjectaccessreviews</code>,请求头里有 <code>Impersonate-User: alice</code>,返回 <code>201 Created</code>。自己提交 <code>SelfSubjectAccessReview</code> 得到 <code>allowed=true</code> 和 <code>reason: RBAC: allowed by RoleBinding "alice-reader/k86" of Role "pod-reader" to User "alice"</code>——能告诉你是哪条绑定放行的。直接提交 <code>SubjectAccessReview</code>(<code>spec.user=alice</code>)结果相同;<code>delete pods</code> 是 <code>allowed=false</code> 且 reason 为空;给它加上 <code>groups: [system:masters]</code> 后 delete 变成 <code>allowed=true</code>、reason 为空——超级用户组由专门的授权器放行,没有 RBAC 的理由。</p>'),
     ('--list', '<p><code>kubectl auth can-i --list -n k86 --as=alice</code> 共 22 行,其中和 pod-reader 相关的是 <code>pods [get list]</code>、<code>configmaps [app-cfg] [get update]</code>、<code>pods/log [get]</code>。它背后是 <code>SelfSubjectRulesReview</code>:直接提交得到 <code>incomplete=False</code>、<code>resourceRules</code> 5 条、<code>nonResourceRules</code> 2 条。这个列表是规则展开,适合人看;要精确判断某个具体操作,还是用具体的 can-i 或 <code>SubjectAccessReview</code>(<code>incomplete=true</code> 时尤其不能依赖列表,比如集群配了 Webhook 授权器)。</p>'),
     ('小陷阱', '<p>资源名写错(<code>podz</code>)只给 <code>Warning: the server doesn\'t have a resource type \'podz\'</code>,结果仍是 <code>no</code>,所以 “no” 不一定是没权限;<code>--subresource=log</code> 查 <code>get pods/log</code>;<code>-q</code> 不输出,只用退出码;<code>--as=alice --as-group=system:masters</code> 的 delete pods → yes——模拟时 <code>--as-group</code> 会改变结果。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,kubectl v1.36);alice 是一个不存在的用户,权限来自命名空间 k86 里的 Role 和 RoleBinding;“管理员”用于 --as 模拟;kubectl -v=8 的请求体是 protobuf 不可读,所以另外用 kubectl create -f 直接提交三种 Review 对象看 JSON;每种情形各一次',
     '没有验证:Webhook 授权器 / Node 授权器 / ABAC 下 SubjectAccessReview 的 reason 与 incomplete;LocalSubjectAccessReview(命名空间级);SelfSubjectReview 与 auth whoami;审计日志里 SubjectAccessReview 的记录;大规模 RoleBinding 下 can-i --list 的耗时'],
    'auth can-i', PANELS)
